function validate([nums, andValues]) {
  const n = nums.length, m = andValues.length;
  if (n < 1 || n > 10000) return 'nums needs 1 to 10^4 values.';
  if (m < 1 || m > Math.min(n, 10)) return 'andValues needs 1 to min(n, 10) values.';
  if (nums.some(v => v < 1 || v >= 100000)) return 'Each value of nums is from 1 to 99999.';
  if (andValues.some(v => v < 0 || v >= 100000)) return 'Each value of andValues is from 0 to 99999.';
  return null;
}

