function minimumValueSum(nums, andValues) {
  const m = andValues.length;
  const START = -1;
  const keepMin = (map, key, value) => {
    if (!map.has(key) || value < map.get(key)) map.set(key, value);
  };
  let dp = Array.from({ length: m + 1 }, () => new Map());
  dp[0].set(START, 0);
  for (const num of nums) {
    const next = Array.from({ length: m + 1 }, () => new Map());
    for (let j = 0; j < m; j++) {
      for (const [running, sum] of dp[j]) {
        const and = running & num;
        if ((and & andValues[j]) !== andValues[j]) continue;
        keepMin(next[j], and, sum);
        if (and === andValues[j]) {
          keepMin(next[j + 1], START, sum + num);
        }
      }
    }
    dp = next;
  }
  return dp[m].has(START) ? dp[m].get(START) : -1;
}

