function minimumValueSum(nums, andValues) {
  // Try every way to cut nums into andValues.length pieces, computing each piece's AND from scratch.
  const n = nums.length, m = andValues.length;
  let best = Infinity;
  const place = (start, piece, total) => {
    if (piece === m) {
      if (start === n) best = Math.min(best, total);
      return;
    }
    for (let end = start; end < n; end++) {
      let and = nums[start];
      for (let k = start + 1; k <= end; k++) and &= nums[k];
      if (and === andValues[piece]) place(end + 1, piece + 1, total + nums[end]);
    }
  };
  place(0, 0, 0);
  return best === Infinity ? -1 : best;
}

