function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : pick(1, 10);
  const m = large ? 10 : pick(1, Math.min(n, 10));
  // Values made of a few bits that are usually set keep the ANDs of short pieces above zero.
  const width = large ? 16 : pick(2, 4);
  const density = large ? 0.8 + rand() * 0.17 : 0.55 + rand() * 0.4;
  const shared = large && rand() < 0.5 ? 1 << pick(0, width - 1) : 0;
  const nums = Array.from({ length: n }, () => {
    let value = shared;
    for (let bit = 0; bit < width; bit++) if (rand() < density) value |= 1 << bit;
    return value || 1;
  });
  // Cut nums into m pieces and use their ANDs, so at least one cut works.
  let ends;
  if (large) {
    // Short pieces keep many bits and long ones lose them, so the requirements vary.
    ends = [];
    let at = 0;
    for (let j = 0; j < m - 1; j++) {
      at += rand() < 0.6 ? pick(1, 6) : pick(1, 200);
      ends.push(at);
    }
    ends.push(n);
  } else {
    const cuts = new Set();
    while (cuts.size < m - 1) cuts.add(pick(1, n - 1));
    ends = [...cuts].sort((a, b) => a - b).concat(n);
  }
  let start = 0;
  const andValues = ends.map(end => {
    let and = nums[start];
    for (let i = start + 1; i < end; i++) and &= nums[i];
    start = end;
    return and;
  });
  // Sometimes change one requirement of a small input, which may make the answer -1.
  if (!large && rand() < 0.25) andValues[pick(0, m - 1)] = pick(0, (1 << width) - 1);
  return [nums, andValues];
}
